type Handler<Args extends unknown[]> = (...args: Args) => void;

class EventEmitter<Events extends Record<string, unknown[]>> {
  private handlers = new Map<keyof Events, Set<Handler<unknown[]>>>();

  on<K extends keyof Events>(key: K, fn: Handler<Events[K]>): this {
    let set = this.handlers.get(key);
    if (!set) {
      set = new Set();
      this.handlers.set(key, set);
    }
    set.add(fn as Handler<unknown[]>);
    return this;
  }

  off<K extends keyof Events>(key: K, fn: Handler<Events[K]>): this {
    const set = this.handlers.get(key);
    if (set) {
      set.delete(fn as Handler<unknown[]>);
      if (set.size === 0) this.handlers.delete(key);
    }
    return this;
  }

  emit<K extends keyof Events>(key: K, ...args: Events[K]): void {
    const set = this.handlers.get(key);
    if (!set) return;
    for (const fn of [...set]) {
      (fn as Handler<Events[K]>)(...args);
    }
  }
}

// ---------- 最小用法示例 ----------
interface MyEvents {
  ping: [number];
  data: [string, boolean];
}

const bus = new EventEmitter<MyEvents>();

const onPing = (n: number) => console.log('ping:', n);

bus.on('ping', onPing);
bus.on('data', (s, b) => {
  // s: string, b: boolean（自动推导）
  console.log('data:', s, b);
});

bus.emit('ping', 42);            // ✅ ping: 42
bus.emit('data', 'hello', true); // ✅ data: hello true

bus.off('ping', onPing);
bus.emit('ping', 42);            // 已取消订阅，无输出

bus.emit('ping', 'oops');        // ❌ 编译错误：string 不能赋给 number
bus.emit('other', 1);            // ❌ 编译错误：不存在的事件名
