class EventEmitter<Events extends Record<string, unknown[]>> {
  private handlers: {
    [K in keyof Events]?: Array<(...args: Events[K]) => void>;
  } = {};

  on<K extends keyof Events>(key: K, fn: (...args: Events[K]) => void): void {
    const list = this.handlers[key];
    if (list) {
      list.push(fn);
    } else {
      this.handlers[key] = [fn];
    }
  }

  off<K extends keyof Events>(key: K, fn: (...args: Events[K]) => void): void {
    const list = this.handlers[key];
    if (!list) return;
    const index = list.indexOf(fn);
    if (index !== -1) list.splice(index, 1);
  }

  emit<K extends keyof Events>(key: K, ...args: Events[K]): void {
    const list = this.handlers[key];
    if (!list) return;
    for (const fn of [...list]) {
      fn(...args);
    }
  }
}

